import '@kerfjs/ui/layout.css';
import '@kerfjs/ui/sidebar.css';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { ToolbarText } from '@kerfjs/ui/toolbar-text';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { ResizableRegion } from '@kerfjs/ui/resizable-region';
import { wireResizableRegions } from '@kerfjs/ui/wire-resizable-regions';
import { signal } from 'kerfjs';

export function createWorkspaceShell() {
  const inspectorSize = signal(Number(localStorage.getItem('inspector-size')) || 320);
  const selected = signal('inbox');
  const persistSize = (size: number) => { inspectorSize.value = size; localStorage.setItem('inspector-size', String(size)); };
  const render = () => <div class="workspace-shell kui-layout" data-action-root>
    <header><Toolbar label="Acme workspace" leading={<ToolbarText text="Acme" />} trailing={<button type="button" data-action="new-item">New item</button>} /></header>
    <div class="workspace-shell__body">
      <nav class="workspace-shell__nav kui-sidebar kui-scroll-owner" aria-label="Workspace navigation"><MenuHeader label="Workspace" /><MenuItem action="select-section" itemId="inbox" label="Inbox" selected={selected.value === 'inbox'} /><MenuItem action="select-section" itemId="projects" label="Projects" selected={selected.value === 'projects'} /></nav>
      <main class="workspace-shell__main" tabindex="-1"><div class="kui-pane-body kui-scroll-owner"><h1>Inbox</h1><p>Workspace content has its own scroll boundary.</p></div></main>
      <ResizableRegion class="workspace-shell__inspector" label="Inspector" value={inspectorSize.value} min={240} max={520} onChange={persistSize}><aside class="kui-pane-body kui-scroll-owner" aria-label="Inspector"><h2>Inspector</h2><p>Select an item to inspect its details.</p></aside></ResizableRegion>
    </div>
  </div>;
  const dispose = wireResizableRegions(document.body);
  return { render, dispose, action(command: string, element: HTMLElement) { if (command === 'select-section' && element.dataset.itemId) selected.value = element.dataset.itemId; } };
}

