.workspace-shell { height: 100dvh; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.workspace-shell__body { display: grid; grid-template-columns: 16rem minmax(0, 1fr) auto; min-height: 0; }
.workspace-shell__nav, .workspace-shell__main, .workspace-shell__inspector { min-height: 0; }
.workspace-shell__nav { border-inline-end: 1px solid var(--kui-color-border); }
.workspace-shell__inspector { border-inline-start: 1px solid var(--kui-color-border); }
@media (max-width: 44rem) { .workspace-shell__body { grid-template-columns: minmax(0, 1fr); } .workspace-shell__nav { display: none; } .workspace-shell__inspector { display: none; } }
